1	import AppKit
2	
3	/// Clip ▸ Follow Subject… (road map "creator-jobs" VR2b2, spec §11 VR-29) — the menu door over
4	/// `reframe_clip`: the selection's targets (`FollowSubject.targets`), the sheet
5	/// (`FollowSubjectSheetController`), and, when the sheet's Follow needs an analysis made, the
6	/// Analyzing sheet and the commit. The sheet commits itself when nothing is missing, or for
7	/// Center, which never analyzes.
8	///
9	/// The Analyzing sheet's hand-back is not an AppKit event, so the plan goes through
10	/// `performGroupedEdit` (Split at Shot Changes' shape), and only onto the project handle and
11	/// scope the hand-off read: a changed project is refused in VR-29 (d)'s sentence. The subjects
12	/// are read off main, then the project is checked again. Every refusal beeps and puts its
13	/// sentence at the inspector's foot (spec §11 CI-10).
14	extension EditorViewController {
15	
16	    @objc func showFollowSubjectSheet(_ sender: Any?) {
17	        guard let document, view.window?.attachedSheet == nil else {
18	            NSSound.beep()
19	            return
20	        }
21	        let targets = FollowSubject.targets(document.selection, in: document.editedProject)
22	        guard !targets.isEmpty else {
23	            NSSound.beep()
24	            return
25	        }
26	        presentAsSheet(
27	            FollowSubjectSheetController(document: document, clips: targets) {
28	                [weak self, weak document] settings, requests in
29	                guard let self, let document else { return }
30	                self.analyzeForFollow(
31	                    settings, requests: requests, targets: targets, document: document)
32	            })
33	    }
34	
35	    /// The sheet's hand-off: the Analyzing sheet over every missing request, one row each.
36	    private func analyzeForFollow(
37	        _ settings: FollowSubjectSettings, requests: [AnalysisRequest], targets: [UInt32],
38	        document: ProjectDocument
39	    ) {
40	        guard view.window?.attachedSheet == nil else {
41	            NSSound.beep()
42	            return
43	        }
44	        let asked = document.project
45	        let scope = document.scope
46	        let rows = requests.map {
47	            AnalyzingSheetController.Row(name: FollowSubject.rowName($0), request: $0)
48	        }
49	        presentAsSheet(
50	            AnalyzingSheetController(
51	                document: document, command: FollowSubject.actionName, rows: rows
52	            ) { [weak self, weak document] outcome in
53	                guard let self, let document else { return }
54	                self.finishFollow(
55	                    outcome, rows: rows, settings: settings, targets: targets, asked: asked,
56	                    scope: scope, document: document)
57	            })
58	    }
59	
60	    /// The Analyzing sheet's answer: refused when the project or scope changed, a failed
61	    /// analysis named; else the subjects read off main and the plan committed.
62	    private func finishFollow(
63	        _ outcome: AnalyzingSheetController.Outcome, rows: [AnalyzingSheetController.Row],
64	        settings: FollowSubjectSettings, targets: [UInt32], asked: ReelProject, scope: UInt32?,
65	        document: ProjectDocument
66	    ) {
67	        guard document.project === asked, document.scope == scope else {
68	            refuseFollow(Self.followChanged, document: document)
69	            return
70	        }
71	        switch outcome {
72	        case .failed(let name, let why):
73	            let request = rows.first { $0.name == name }?.request
74	            let kind = request?.kind.rawValue ?? "framing"
75	            let file = request?.media.name ?? name
76	            refuseFollow("The \(kind) analysis of “\(file)” failed: \(why).", document: document)
77	        case .landed:
78	            guard let cacheDir = document.cacheDirectory else {
79	                refuseFollow(
80	                    ProjectDocument.AnalysisRequestError.noCache.localizedDescription,
81	                    document: document)
82	                return
83	            }
84	            let project = document.editedProject
85	            DispatchQueue.global(qos: .userInitiated).async { [weak self, weak document] in
86	                let subjects = FollowSubject.subjects(targets, in: project, cacheDir: cacheDir)
87	                DispatchQueue.main.async {
88	                    guard let self, let document else { return }
89	                    guard document.project === asked, document.scope == scope else {
90	                        self.refuseFollow(Self.followChanged, document: document)
91	                        return
92	                    }
93	                    self.commitFollow(
94	                        targets, subjects: subjects, settings: settings, document: document)
95	                }
96	            }
97	        }
98	    }
99	
100	    /// The plan on the current handle, as one explicit undo group; nothing framed is refused
101	    /// with the summary's lines.
102	    private func commitFollow(
103	        _ targets: [UInt32], subjects: [UInt32: [String: Any]], settings: FollowSubjectSettings,
104	        document: ProjectDocument
105	    ) {
106	        let answer: FollowSubject.Answer
107	        do {
108	            answer = try FollowSubject.plan(
109	                targets, subjects: subjects, settings: settings, project: document.editedProject)
110	        } catch {
111	            refuseFollow(error.localizedDescription, document: document)
112	            return
113	        }
114	        switch answer {
115	        case .refused(let why):
116	            refuseFollow(why, document: document)
117	        case .plan(let plan) where plan.ops.isEmpty:
118	            refuseFollow(FollowSubject.summary(plan), document: document)
119	        case .plan(let plan):
120	            document.performGroupedEdit(FollowSubject.actionName, plan.ops)
121	        }
122	    }
123	
124	    private static let followChanged =
125	        "the project changed while \(FollowSubject.actionName) was analyzing, so nothing was "
126	        + "framed. Choose \(FollowSubject.actionName) again."
127	
128	    /// A beep and the sentence at the inspector's foot.
129	    private func refuseFollow(_ reason: String, document: ProjectDocument) {
130	        NSSound.beep()
131	        NotificationCenter.default.post(
132	            name: .projectDocumentDidRefuse, object: document,
133	            userInfo: ["refusal": ReelRefusal(op: "reframe_clip", reason: reason)])
134	    }
135	
136	    /// The menu arm, answered from `validateUserInterfaceItem`'s default case; nil for any other
137	    /// action. On when a selected clip of the edited container has a moving picture and no
138	    /// sheet is on the window; allowed inside a nest.
139	    func validateFollowSubjectAction(_ action: Selector) -> Bool? {
140	        guard action == #selector(showFollowSubjectSheet(_:)) else { return nil }
141	        guard let document, view.window?.attachedSheet == nil else { return false }
142	        return !FollowSubject.targets(document.selection, in: document.editedProject).isEmpty
143	    }
144	}
