265	    /// VR-29 (g)'s pending summary, while the analysis is still to be made.
266	    static func pendingSummary(files: Int, clips: Int) -> String {
267	        "Finds the faces, people and shot changes in \(counted(files, "file")) on this Mac "
268	            + "first, then frames \(counted(clips, "clip"))."
269	    }
