3	/// What a VR command analyses (spec §11 VR-12; road map "creator-jobs" VR1):
4	/// for each media the named clips show, the windows those clips play plus
5	/// `margin` each side, in the order `kinds` — `shots`, `faces`, `subjects`.
6	/// CJ-20 stands: nothing runs at import; a command wants these requests and
7	/// waits, as Split at Shot Changes does. `reframe_clip`'s tool (VR2a2,
8	/// VR-28), Clip ▸ Follow Subject… (`FollowSubject.swift`, VR-29) and
9	/// `analysis_job {clips}` (dev, the proof's door) call it; View ▸ Show
10	/// Subjects never does (VR-13).
11	///
12	/// Names no `rc_*`; `requests` is main only (it reads the document).
13	enum FramingAnalysis {
14	    /// One second each side of a played window (VR-12).
15	    static let margin: Ticks = 600_000
16	    /// The kinds a framing reads, in the order they are wanted.
17	    static let kinds: [AnalysisKind] = [.shots, .faces, .subjects]
18	
19	    /// One media's windows, in forward-media source ticks [lower, upper),
20	    /// merged where they overlap or touch, in time order.
21	    struct MediaWindows: Equatable {
22	        let media: UInt32
23	        let windows: [ClosedRange<Ticks>]
24	    }
25	
26	    /// Each media clip among `clips` whose media has a moving picture, in
27	    /// order, its media grouped in the order of first appearance; each window
28	    /// the clip's played window (`AnalysisClipTimes`, through its source map,
29	    /// speed and reversal) widened by `margin` each side and clamped to
30	    /// 0…duration, merged per media. Text, shape, graphic, adjustment and nest
31	    /// clips, and clips of an audio file or a still, are skipped.
32	    static func windows(clips: [UInt32], in project: ReelProject) -> [MediaWindows] {
33	        let snapshot = project.snapshot
34	        var order: [UInt32] = []
35	        var found: [UInt32: [ClosedRange<Ticks>]] = [:]
36	        for id in clips {
37	            guard let clip = snapshot.clip(id), qualifies(clip, in: snapshot),
38	                case .media(let mediaID, _, _) = clip.source, let media = snapshot.media(mediaID)
39	            else { continue }
40	            let played = AnalysisClipTimes(clip: clip, media: media, map: project.sourceMap(id))
41	                .window
42	            let lower = max(0, played.lowerBound - margin)
43	            let upper = min(max(0, media.duration), played.upperBound + margin)
44	            guard lower <= upper else { continue }
45	            if found[mediaID] == nil { order.append(mediaID) }
46	            found[mediaID, default: []].append(lower...upper)
47	        }
48	        return order.map { MediaWindows(media: $0, windows: merged(found[$0] ?? [])) }
49	    }
50	
51	    /// Whether `clip` is one `windows` reads: a media clip whose media is a
52	    /// video with a moving picture (spec §11 VR-29 (a)).
53	    static func qualifies(_ clip: ClipSnapshot, in snapshot: ProjectSnapshot) -> Bool {
54	        guard case .media(let mediaID, _, _) = clip.source, let media = snapshot.media(mediaID)
55	        else { return false }
56	        return media.kind == .video && media.hasVideo
57	    }
58	
59	    /// Every request `kinds` need over `windows(clips:in:)` of `project` —
60	    /// the document's open scope when nil, else the container a call named
61	    /// (`reframe_clip`'s, spec §11 VR-28): kind-major in `kinds` order, then
62	    /// media in the windows' order, each kind's need the windows' grid indices
63	    /// widened by its read margin
64	    /// (`ProjectDocument.analysisRequest(kind:media:url:urls:cacheDir:need:)`);
65	    /// a hit is omitted. Throws the request's own errors (a missing file, no
66	    /// cache folder, an unreadable file). Main thread.
67	    static func requests(
68	        clips: [UInt32], in document: ProjectDocument, project: ReelProject? = nil
69	    ) throws -> [AnalysisRequest] {
70	        let project = project ?? document.editedProject
71	        let all = windows(clips: clips, in: project)
72	        guard !all.isEmpty else { return [] }
73	        let urls = document.mediaURLs()
74	        guard let cacheDir = document.cacheDirectory else {
75	            throw ProjectDocument.AnalysisRequestError.noCache
76	        }
77	        var requests: [AnalysisRequest] = []
78	        for kind in kinds {
79	            for entry in all {
80	                guard let media = project.snapshot.media(entry.media) else { continue }
81	                guard let url = urls[entry.media] else {
82	                    throw ProjectDocument.AnalysisRequestError.missingFile(entry.media)
83	                }
84	                let grid = kind.grid(of: media)
85	                let need = entry.windows.compactMap {
86	                    grid.indices(from: $0.lowerBound, to: $0.upperBound)
87	                }.map { grid.need($0, margin: kind.margin) }
88	                guard !need.isEmpty else { continue }
89	                if let request = try ProjectDocument.analysisRequest(
90	                    kind: kind, media: media, url: url, urls: urls, cacheDir: cacheDir,
91	                    need: need)
92	                {
93	                    requests.append(request)
94	                }
95	            }
96	        }
97	        return requests
98	    }
99	
100	    /// Tick ranges merged where they overlap or touch, in order.
101	    static func merged(_ ranges: [ClosedRange<Ticks>]) -> [ClosedRange<Ticks>] {
102	        var out: [ClosedRange<Ticks>] = []
103	        for range in ranges.sorted(by: { $0.lowerBound < $1.lowerBound }) {
104	            if let last = out.last, range.lowerBound <= last.upperBound {
105	                out[out.count - 1] = last.lowerBound...max(last.upperBound, range.upperBound)
106	            } else {
107	                out.append(range)
108	            }
109	        }
110	        return out
111	    }
112	}
