376	/// The planner (spec §11 VR-20…VR-24). `None` for: no such clip, not a
377	/// media clip of a video media, a base rotation other than 0, a media with
378	/// no size, a crop or scale that leaves no picture, a zoom outside 1…4, or a
379	/// zero `from_width`/`from_height`. VR2a2 refuses each by name before
380	/// calling.
381	pub fn plan_framing(
382	    project: &Project,
383	    clip: u32,
384	    subjects: &Subjects,
385	    request: &FramingRequest,
386	    tuning: &FramingTuning,
387	) -> Option<FramingPath> {
388	    let clip = project.clip(clip)?;
389	    let Source::Media { media, .. } = clip.source else {
390	        return None;
391	    };
392	    let media = project.media(media)?;
393	    if media.kind != MediaKind::Video || !media.has_video {
394	        return None;
395	    }
396	    let mut frame = Frame::of(project, clip, request)?;
397	    let (samples, shots) = in_clip_time(clip, project, subjects);
398	    if !clip.actions.is_empty() {
399	        frame.placed = samples
400	            .iter()
401	            .map(|s| {
402	                let p = project.evaluate_clip(clip, s.t).video;
403	                (s.t, p.scale, p.x, p.y)
404	            })
405	            .collect();
406	    }
407	    let chosen = choose_subject(&samples, &shots, request.follow);
408	    Some(write_keys(
409	        &frame,
410	        &chosen,
411	        &shots,
412	        clip.duration,
413	        project.canvas.fps,
414	        request,
415	        tuning,
416	    ))
417	}
418	
419	/// One key at 0 holding a `where_empty` state for the whole clip (spec §11
420	/// VR-24 (h), VR-26): `follow` `center` (the window at fill × `zoom` on the
421	/// cropped centre) and `fit` (the cropped picture fitted; `zoom` unread).
422	/// `None` for no such clip, no size, a base rotation other than 0, a zoom
423	/// outside 1…4, or a crop or scale that leaves no picture. Offsets are
424	/// measured from the canvas's own centre, so the source canvas is the
425	/// current one.
426	pub fn fixed_framing(
427	    project: &Project,
428	    clip: u32,
429	    state: WhereEmpty,
430	    zoom: f64,
431	) -> Option<FramingPath> {
432	    let clip = project.clip(clip)?;
433	    let request = FramingRequest {
434	        follow: Follow::Subject,
435	        zoom,
436	        from_width: project.canvas.width,
437	        from_height: project.canvas.height,
438	        where_empty: state,
439	    };
440	    let frame = Frame::of(project, clip, &request)?;
441	    let key = match state {
442	        WhereEmpty::Center => frame.key(0, frame.centre(), Curve::Linear),
443	        WhereEmpty::Fit => frame.fit_key(0, Curve::Linear),
444	    };
445	    Some(FramingPath {
446	        keys: vec![key],
447	        shows_fit: state == WhereEmpty::Fit,
448	        cuts: Vec::new(),
449	    })
450	}
