/// F′ as keys, read exactly at a key and eased between (`FramingPath::at`).
fn at(keys: &[FramingKey], t: Ticks) -> Value3 {
    if let Some(k) = keys.iter().find(|k| k.t == t) {
        return (k.scale, k.x, k.y);
    }
    FramingPath {
        keys: keys.to_vec(),
        shows_fit: false,
        cuts: Vec::new(),
    }
    .at(t)
}

